<script setup lang="ts">
import {onMounted,ref} from 'vue';
const props=defineProps<{name:string;csrf?:string;modal?:boolean;destination?:string;initialError?:string}>();
const emit=defineEmits<{close:[];busy:[value:boolean]}>();
const email=ref(''),password=ref(''),visible=ref(false),busy=ref(false),error=ref(props.initialError||''),expired=ref(false),emailField=ref<HTMLInputElement|null>(null);
onMounted(()=>{if(props.modal)emailField.value?.focus();});
function reloadPage(){window.location.reload();}
async function submit(){
 if(busy.value)return;busy.value=true;emit('busy',true);error.value='';expired.value=false;const controller=new AbortController();const timeout=window.setTimeout(()=>controller.abort(),20000);
 try{
  const token=props.csrf||document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content||'';
  const response=await fetch('/login',{signal:controller.signal,method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({email:email.value,password:password.value,...(props.destination?{redirect_to:props.destination}:{})})});
  const data=await response.json().catch(()=>({}));
  if(response.status===419){expired.value=true;throw Error('Your session expired. Reload the page and try again.');}
  if(response.status===429)throw Error('Too many sign-in attempts. Please wait a moment and try again.');
  if(!response.ok)throw Error(Object.values(data.errors||{}).flat().join(' ')||data.message||'Unable to sign in. Please try again.');
  const destination=new URL(data.redirect||'/products',location.origin);
  if(destination.origin!==location.origin)throw Error('Unable to open the workspace. Please sign in again.');
  window.location.assign(destination.href);
 }catch(e:any){error.value=e.name==='AbortError'?'Sign-in timed out. Please try again.':e.message||'Unable to connect. Please try again.';busy.value=false;emit('busy',false);}finally{window.clearTimeout(timeout);}
}
</script>
<template><section class="judibas-login-panel" :aria-busy="busy"><button v-if="modal" type="button" class="login-close" aria-label="Close login" :disabled="busy" @click="emit('close')">×</button><a class="login-brand" href="/" :tabindex="busy?-1:undefined"><span class="login-brand-mark" aria-hidden="true">{{name.charAt(0).toUpperCase()}}</span>{{name}}</a><h1 id="judibas-login-title">Welcome back</h1><p class="login-subtitle">{{modal?'Sign in to explore your products and workspace.':'Sign in with your company email and password.'}}</p><form @submit.prevent="submit"><label for="judibas-login-email">Email address</label><div class="login-input-wrap"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h18v14H3z M3 6l9 7 9-7"/></svg><input id="judibas-login-email" ref="emailField" :autofocus="modal" v-model="email" name="email" type="email" autocomplete="username" placeholder="you@company.com" maxlength="254" required :disabled="busy" :aria-describedby="error?'judibas-login-error':undefined"></div><label for="judibas-login-password">Password</label><div class="login-input-wrap"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 11h12v10H6z M8 11V7a4 4 0 0 1 8 0v4"/></svg><input id="judibas-login-password" v-model="password" name="password" :type="visible?'text':'password'" autocomplete="current-password" placeholder="Enter your password" maxlength="200" required :disabled="busy" :aria-describedby="error?'judibas-login-error':undefined"><button type="button" class="login-password-toggle" :aria-label="visible?'Hide password':'Show password'" :aria-pressed="visible" :disabled="busy" @click="visible=!visible"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path v-if="visible" d="m3 3 18 18"/></svg></button></div><p v-if="error" id="judibas-login-error" class="login-error" role="alert">{{error}} <button v-if="expired" type="button" @click="reloadPage">Reload page</button></p><button type="submit" class="login-submit" :disabled="busy"><span v-if="busy" class="login-spinner" aria-hidden="true"></span>{{busy?'Signing in…':modal?'Sign in & open Products':'Sign in'}}<span v-if="!busy" aria-hidden="true">→</span></button></form><p class="login-support">Need access? <span>Contact your administrator</span></p><div class="login-security"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7z M8 12l3 3 5-6"/></svg>One account for your {{name}} workspace</div></section></template>
<style scoped>
.judibas-login-panel{position:relative;width:100%;padding:30px 32px 23px;box-sizing:border-box;background:var(--bg,#fff);color:var(--text,#25252c);font-size:13px;line-height:1.5;--login-accent:#7458ed}.login-brand{display:flex;align-items:center;gap:10px;width:fit-content;color:inherit;text-decoration:none;font-size:16px;font-weight:650}.login-brand-mark{display:flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:10px;background:var(--login-accent);color:#fff;font-size:20px}.judibas-login-panel h1{font:650 27px/1.2 var(--font,Arial,sans-serif);letter-spacing:-.8px;margin:29px 0 9px}.login-subtitle{font-size:13px;line-height:1.7;color:var(--muted,#8b899b);margin:0 0 25px}.judibas-login-panel label{display:block;font-size:12px;font-weight:600;margin:19px 0 9px}.login-input-wrap{display:flex;align-items:center;gap:10px;height:46px;border:1px solid var(--line,#e4e1ec);border-radius:9px;padding:0 13px;background:var(--bg,#fff);transition:border-color .15s,box-shadow .15s}.login-input-wrap:focus-within{border-color:var(--login-accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--login-accent) 12%,transparent)}.login-input-wrap>svg{flex-shrink:0;width:17px;height:17px;color:var(--muted,#aaa5bc)}.login-input-wrap input{flex:1;min-width:0;width:100%;border:0!important;outline:0!important;box-shadow:none!important;border-radius:0;background:transparent!important;padding:0!important;height:100%;font:inherit;font-size:13px;color:var(--text,#25252c)}.login-input-wrap input::placeholder{color:var(--muted,#aaa7b8);opacity:.8}.judibas-login-panel svg{fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.judibas-login-panel .login-password-toggle{display:flex;align-items:center;justify-content:center;min-width:30px;min-height:32px;margin-right:-6px;background:transparent;border:0;padding:5px;color:var(--muted,#9994ab);cursor:pointer}.login-password-toggle svg{width:17px;height:17px}.judibas-login-panel .login-submit{display:flex;align-items:center;justify-content:center;gap:15px;width:100%;height:46px;margin-top:26px;border:0;border-radius:9px;background:var(--login-accent);color:white;font:600 12px/1.4 var(--font,Arial,sans-serif);cursor:pointer;box-shadow:0 4px 10px #7458ed19}.login-submit>span:not(.login-spinner){font-size:19px;font-weight:400}.login-submit:hover{filter:brightness(.96)}.judibas-login-panel button:disabled{opacity:.65;cursor:wait}.judibas-login-panel button:focus-visible,.login-brand:focus-visible{outline:2px solid var(--login-accent);outline-offset:3px}.login-support{text-align:center;color:var(--muted,#9692a5);font-size:10px;line-height:1.7;margin:20px 0 2px}.login-support span{font-weight:500}.login-security{display:flex;align-items:center;justify-content:center;gap:7px;font-size:10px;line-height:1.5;text-align:center;color:var(--muted,#aaa4ba);padding-top:18px;margin-top:22px;border-top:1px solid var(--line,#eeecf4)}.login-security svg{width:13px;height:13px;flex-shrink:0}.judibas-login-panel .login-close{position:absolute;right:17px;top:15px;display:flex;align-items:center;justify-content:center;width:29px;height:29px;border:0;border-radius:50%;background:color-mix(in srgb,var(--muted,#93929f) 9%,var(--bg,#fff));color:var(--muted,#93929f);font-size:21px;cursor:pointer;padding:0}.login-error{margin:16px 0 0;padding:10px 12px;color:light-dark(#ac293d,#ffb5bc);background:color-mix(in srgb,#d14c60 9%,var(--bg,#fff));border:1px solid color-mix(in srgb,#d14c60 35%,var(--line,#eee));border-radius:8px;font-size:12px}.login-error button{font:inherit;border:0;background:none;color:inherit;text-decoration:underline;cursor:pointer}.login-spinner{width:15px;height:15px;border:2px solid #ffffff55;border-top-color:white;border-radius:50%;animation:login-spin .7s linear infinite}@keyframes login-spin{to{transform:rotate(360deg)}}@media(max-width:480px){.judibas-login-panel{padding:28px 24px 22px}.judibas-login-panel h1{font-size:25px}.login-subtitle{font-size:12px}}@media(prefers-reduced-motion:reduce){.login-spinner{animation:none}.login-input-wrap{transition:none}}
</style>
